package executors

import (
	"context"
	"fmt"
	"time"

	"github.com/kiff/kiff/pkg/kiff/action"
	"github.com/kiff/kiff/pkg/kiff/event"
)

// CloudProxy is a generic executor that domains generated by the
// guided builder point at. The guided builder produces a
// kiff.yaml that maps the action's executor key to "cloud.proxy"
// because the customer runs the actual side-effect in their own
// code: their app POSTs to /v1/proposals/decide before its
// risky function runs, branches on the decision, and then
// executes its own function. KIFF is the gate, not the runner.
//
// CloudProxy exists so the YAML validator's executor-key
// membership check passes for tenant-built domains. If a
// customer ever calls /v1/entities/{id}/actions/{name}/execute
// against a cloud.proxy-backed action, this returns a successful
// no-op result with a clear message — the cloud has no business
// running customer logic.
//
// Side-effect-free, deterministic, no follow-up events.
func CloudProxy(_ context.Context, ctx action.ActionContext) (action.ActionResult, error) {
	return action.ActionResult{
		ActionName:     ctx.ActionName,
		EntityID:       ctx.EntityID,
		Status:         action.ExecutionSucceeded,
		Executed:       true,
		Message:        fmt.Sprintf("proposal accepted; %s runs in your application code", ctx.ActionName),
		EffectsSummary: "no-op (customer code runs the side effect)",
		FollowUpEvents: []event.Event{},
		ExecutedAt:     time.Now().UTC(),
	}, nil
}
